rep='''        if(wagePanel!=null){ wagePanel.setDisplayedMonth(displayedMonth); totalWageText.setText(String.format(Locale.UK,"£%.2f",wagePanel.getDisplayedMonthWage())); }\n        rebuildSharedCalendar(today);\n    }'''
if needle not in s: raise SystemExit('refresh month end missing')
s=s.replace(needle,rep,1)
